package com.antra.ticket; import com.fasterxml.jackson.annotation.JsonAutoDetect; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="reservations") @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class Reservation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String username; @Column(nullable=false) Long eventId; @Column(nullable=false) int quantity; @Column(nullable=false) BigDecimal totalPrice; @Column(nullable=false) String status="PENDING"; @Column(nullable=false) Instant createdAt=Instant.now(); protected Reservation(){} Reservation(String user,Long event,int count,BigDecimal price){username=user;eventId=event;quantity=count;totalPrice=price.multiply(BigDecimal.valueOf(count));} }
